import Foundation

// Guided lessons — port of src/utils/lessonPlan.js, lessonStore.js,
// reviewMix.js, plus the three helpers they lean on that had no Swift twin yet
// (gameRandom.js's seeded PRNG, scramble.js, and the strict drill / transform
// checkers from answer.js and transformDrill.js).
//
// A week becomes a few short, linear lessons over data it already carries.
// Everything is deterministic — seeded by week + lesson — so the plan this
// file builds must equal the web's step for step, shuffle for shuffle. The
// `lessons.json` fixture is generated by running the real JS over every week
// and LessonsTests compares the lot, so **any change to the JS plan, the PRNG
// or the order random numbers are drawn in must be mirrored here**.

// ── gameRandom.js ────────────────────────────────────────────────────────────

/// xmur3 string hash → one 32-bit seed. Hashes UTF-16 units, as JS does.
public func hashSeed(_ str: String) -> UInt32 {
    let units = Array(str.utf16)
    var h: UInt32 = 1_779_033_703 ^ UInt32(truncatingIfNeeded: units.count)
    for u in units {
        h = (h ^ UInt32(u)) &* 3_432_918_353
        h = (h << 13) | (h >> 19)
    }
    h = (h ^ (h >> 16)) &* 2_246_822_507
    h = (h ^ (h >> 13)) &* 3_266_489_909
    return h ^ (h >> 16)
}

/// mulberry32. A class so one generator can be threaded through a whole
/// lesson's shuffles, the way the JS closure is.
public final class SeededRandom {
    private var a: UInt32

    public init(seed: UInt32) { a = seed }
    public convenience init(_ seed: String) { self.init(seed: hashSeed(seed)) }

    /// The next value in [0, 1).
    public func next() -> Double {
        a = a &+ 0x6d2b_79f5
        var t = a
        t = (t ^ (t >> 15)) &* (t | 1)
        t ^= t &+ ((t ^ (t >> 7)) &* (t | 61))
        return Double(t ^ (t >> 14)) / 4_294_967_296
    }

    /// Fisher-Yates on a copy.
    public func shuffled<T>(_ list: [T]) -> [T] {
        var out = list
        guard out.count > 1 else { return out }
        for i in stride(from: out.count - 1, to: 0, by: -1) {
            let j = Int(next() * Double(i + 1))
            out.swapAt(i, j)
        }
        return out
    }
}

// ── scramble.js ──────────────────────────────────────────────────────────────

public let SCRAMBLE_MIN_WORDS = 4
public let SCRAMBLE_MAX_WORDS = 12

/// Whitespace-split chips; punctuation stays attached to its word.
public func scrambleTokens(_ sentence: String) -> [String] {
    sentence.split(whereSeparator: \.isWhitespace).map(String.init)
}

/// Shuffle, guaranteed to differ from the original order when the tokens allow.
public func shuffleScramble(_ tokens: [String], rng: SeededRandom) -> [String] {
    var out = rng.shuffled(tokens)
    if out == tokens {
        for i in 0..<out.count {
            for j in (i + 1)..<max(out.count, i + 1) where out[i] != out[j] {
                out.swapAt(i, j)
                return out
            }
        }
    }
    return out
}

// ── answer.js checkDrill / transformDrill.js checkTransform ──────────────────

private let drillPunctuation: Set<Character> = [".", ",", ";", ":", "!", "?", "\"", "«", "»", "(", ")"]

/// Lowercase, unify apostrophes, drop punctuation, collapse whitespace — but
/// keep every accent. Mirrors drillCanonical().
public func drillCanonical(_ s: String) -> String {
    let mapped = s.lowercased().map { c -> Character in
        (c == "’" || c == "`" || c == "´") ? "'" : c
    }
    let kept = String(mapped.filter { !drillPunctuation.contains($0) })
    return kept.split(whereSeparator: \.isWhitespace).joined(separator: " ")
}

/// Strict grading for grammar drills: accents count, and short forms get no
/// typo tolerance (è vs e, dà vs da). Mirrors checkDrill().
public func checkDrill(expected: String, given: String) -> Bool {
    let e = drillCanonical(expected)
    let g = drillCanonical(given)
    if g.isEmpty { return false }
    if e == g { return true }
    if normalizeText(e) == normalizeText(g) { return false }
    if e.count < 5 { return false }
    return levenshtein(e, g) <= 1
}

private let transformPunctuation: Set<Character> =
    [".", ",", ";", ":", "!", "?", "\"", "«", "»", "'", "’", "`", "(", ")"]

private func transformTokens(_ s: String) -> [String] {
    let spaced = String(normalizeText(s).map { transformPunctuation.contains($0) ? " " : $0 })
    return spaced.split(whereSeparator: \.isWhitespace).map(String.init)
}

/// Exact token-sequence match (accent/case/punctuation folded, no typo
/// tolerance — the transforms themselves are often one character).
public func checkTransform(answer: String, typed: String) -> Bool {
    transformTokens(answer) == transformTokens(typed)
}

/// A week's transformation drills, dropping malformed items.
public func transformItems(_ week: Week) -> [TransformItem] {
    let blank: (String) -> Bool = { $0.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty }
    return (week.transform ?? []).filter { !blank($0.instruction) && !blank($0.base) && !blank($0.answer) }
}

// ── lessonPlan.js ────────────────────────────────────────────────────────────

public let WORDS_PER_LESSON = 4
public let VERSES_PER_LESSON = 2

public struct LessonPair: Equatable {
    public let it: String
    public let en: String
}

/// One screen of a lesson. A flat struct rather than an enum with payloads so
/// a step can be compared field by field with the web's JSON.
public struct LessonStep: Equatable, Identifiable {
    public enum Kind: String {
        case intro, match, choice, cloze, build, recall, tip, drill, tf, mc, transform
    }

    public var id = 0
    public var kind: Kind
    /// True for the second showing of a missed step.
    public var retry = false
    /// The vocab headword this step exercises, when it has one.
    public var term: String?
    public var card: VocabCard?

    // choice: "it-en" | "en-it", and the text asked about
    public var direction: String?
    public var prompt: String?
    // choice / mc
    public var options: [String] = []
    public var answerIndex: Int?
    // tf
    public var answerBool: Bool?
    // match
    public var pairs: [LessonPair] = []
    public var left: [Int] = []
    public var right: [Int] = []
    // cloze: before + answerText + after. drill / transform: answerText.
    public var before: String?
    public var answerText: String?
    public var after: String?
    // build: the sentence. tf / mc: the Italian statement. transform: the base.
    public var text: String?
    public var en: String?
    public var chips: [String] = []
    public var audio = false
    public var partial = false
    public var ref: String?
    // tip
    public var title: String?
    public var body: String?
    // drill
    public var q: String?
    public var hint: String?
    // tf / mc
    public var explain: String?
    // transform
    public var instruction: String?
    /// An extra showing added by adaptLesson: practice only, never graded into the SRS.
    public var practice = false

    public init(_ kind: Kind) { self.kind = kind }

    /// Steps that only present something — no verdict, never re-queued.
    public var isGraded: Bool { kind != .intro && kind != .tip && kind != .match }
    /// Typed from memory: the only steps that are evidence of recall.
    var isTyped: Bool { (kind == .cloze || kind == .recall) && !practice }
}

public struct Lesson: Equatable, Identifiable {
    public enum Kind: String { case words, passage }

    public let key: String
    public let weekN: Int
    public let n: Int
    public let kind: Kind
    public let title: String
    public let sub: String
    public let words: [String]
    public let steps: [LessonStep]
    public let minutes: Int
    /// Set when adaptLesson changed the plan for this learner.
    public var adapted: LessonAdaptation? = nil

    public var id: String { key }
}

public struct LessonAdaptation: Equatable {
    public let skipped: Int
    public let extra: Int
}

/// Split into ceil(n / size) groups of near-equal length, larger first.
public func balancedChunks<T>(_ items: [T], size: Int = WORDS_PER_LESSON) -> [[T]] {
    let n = items.count
    if n == 0 { return [] }
    let groups = Int((Double(n) / Double(size)).rounded(.up))
    let base = n / groups
    var extra = n % groups
    var out: [[T]] = []
    var at = 0
    for _ in 0..<groups {
        let len = base + (extra > 0 ? 1 : 0)
        extra -= 1
        out.append(Array(items[at..<(at + len)]))
        at += len
    }
    return out
}

/// /^[A-ZÀ-Þ]/ on the first UTF-16 unit.
private func isCapitalized(_ s: String) -> Bool {
    guard let u = s.utf16.first else { return false }
    return (0x41...0x5A).contains(u) || (0xC0...0xDE).contains(u)
}

private func wrongOptions(_ pool: [String], correct: String, rng: SeededRandom, n: Int = 3) -> [String] {
    var seen = Set<String>()
    let uniq = pool.filter { !$0.isEmpty && seen.insert($0).inserted && $0 != correct }
    let same = uniq.filter { isCapitalized($0) == isCapitalized(correct) }
    let rest = uniq.filter { !same.contains($0) }
    // Both shuffles always run, in this order — the draw order is the contract.
    let a = rng.shuffled(same)
    let b = rng.shuffled(rest)
    return Array((a + b).prefix(n))
}

private func choiceStep(_ card: VocabCard, all: [VocabCard], rng: SeededRandom, direction: String) -> LessonStep? {
    let pick: (VocabCard) -> String = direction == "it-en" ? { $0.en } : { $0.it }
    let correct = pick(card)
    let wrong = wrongOptions(all.map(pick), correct: correct, rng: rng)
    if wrong.isEmpty { return nil }
    let options = rng.shuffled([correct] + wrong)
    var step = LessonStep(.choice)
    step.direction = direction
    step.term = card.it
    step.prompt = direction == "it-en" ? card.it : card.en
    step.options = options
    step.answerIndex = options.firstIndex(of: correct)
    return step
}

private func buildStep(_ text: String, en: String, rng: SeededRandom) -> LessonStep? {
    let tokens = scrambleTokens(text)
    if tokens.count < SCRAMBLE_MIN_WORDS || tokens.count > SCRAMBLE_MAX_WORDS { return nil }
    var step = LessonStep(.build)
    step.text = text
    step.en = en
    step.chips = shuffleScramble(tokens, rng: rng)
    return step
}

private func sentenceStep(_ card: VocabCard, articles: [String], rng: SeededRandom) -> LessonStep? {
    if let cloze = makeCloze(term: card.it, example: card.ex, articles: articles, form: card.form) {
        var step = LessonStep(.cloze)
        step.term = card.it
        step.card = card
        step.before = cloze.before
        step.answerText = cloze.answer
        step.after = cloze.after
        return step
    }
    var step = buildStep(card.ex, en: card.exEn ?? "", rng: rng)
    step?.term = card.it
    return step
}

private func wordSteps(_ words: [VocabCard], all: [VocabCard], articles: [String], rng: SeededRandom) -> [LessonStep] {
    var steps: [LessonStep] = words.map { card in
        var s = LessonStep(.intro)
        s.term = card.it
        s.card = card
        return s
    }
    if words.count >= 2 {
        let idx = Array(words.indices)
        var s = LessonStep(.match)
        s.pairs = words.map { LessonPair(it: $0.it, en: $0.en) }
        s.left = rng.shuffled(idx)
        s.right = rng.shuffled(idx)
        steps.append(s)
    }
    for card in rng.shuffled(words) {
        if let s = choiceStep(card, all: all, rng: rng, direction: "it-en") { steps.append(s) }
    }
    for card in words {
        if let s = sentenceStep(card, articles: articles, rng: rng) { steps.append(s) }
    }
    for card in rng.shuffled(words) {
        var s = LessonStep(.recall)
        s.term = card.it
        s.card = card
        steps.append(s)
    }
    return steps
}

private func grammarSteps(_ week: Week) -> [LessonStep] {
    var steps: [LessonStep] = []
    if !week.grammar.title.isEmpty, !week.grammar.body.isEmpty {
        var s = LessonStep(.tip)
        s.title = week.grammar.title
        s.body = week.grammar.body
        steps.append(s)
    }
    for d in drillItems(week) {
        var s = LessonStep(.drill)
        s.q = d.q
        s.answerText = d.a
        s.hint = d.hint ?? ""
        steps.append(s)
    }
    return steps
}

/// Split after , ; : when whitespace follows — /(?<=[,;:])\s+/.
private func clauses(_ text: String) -> [String] {
    var out: [String] = []
    var current = ""
    var prev: Character?
    var skipping = false
    for c in text {
        if c.isWhitespace, skipping || prev == "," || prev == ";" || prev == ":" {
            if !skipping { out.append(current); current = "" }
            skipping = true
        } else {
            skipping = false
            current.append(c)
        }
        prev = c
    }
    out.append(current)
    return out
}

/// A verse to rebuild by ear: the whole verse when short enough, otherwise its
/// first clause of buildable length (which carries no English).
private func verseStep(t: String, en: String, ref: String, rng: SeededRandom) -> LessonStep? {
    if var whole = buildStep(t, en: en, rng: rng) {
        whole.audio = true
        whole.ref = ref
        return whole
    }
    for clause in clauses(t) {
        if var step = buildStep(clause, en: "", rng: rng) {
            step.audio = true
            step.ref = ref
            step.partial = true
            return step
        }
    }
    return nil
}

private func passageSteps(_ week: Week, all: [VocabCard], rng: SeededRandom) -> (steps: [LessonStep], recap: [LessonStep]) {
    let trim: (String) -> String = { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
    // Every line is offered to the generator, as in the JS map → filter → slice.
    let verses = (week.passage?.verses ?? [])
        .map { (ref: String($0.n), t: trim($0.t), en: trim($0.en ?? "")) }
        .filter { !$0.t.isEmpty }
        .compactMap { verseStep(t: $0.t, en: $0.en, ref: $0.ref, rng: rng) }
    var steps = Array(verses.prefix(VERSES_PER_LESSON))
    for c in comprehensionItems(week) {
        var s = LessonStep(c.type == "tf" ? .tf : .mc)
        s.text = c.it
        s.en = c.en ?? ""
        s.options = c.options ?? []
        s.answerIndex = c.answerIndex
        s.answerBool = c.answerBool
        s.explain = c.explain ?? ""
        steps.append(s)
    }
    for t in transformItems(week) {
        var s = LessonStep(.transform)
        s.instruction = t.instruction
        s.text = t.base
        s.answerText = t.answer
        steps.append(s)
    }
    let recap = rng.shuffled(all).compactMap { choiceStep($0, all: all, rng: rng, direction: "en-it") }
    return (steps, recap)
}

private let romanNumerals = ["I", "II", "III", "IV", "V", "VI"]

private func finishLesson(_ week: Week, n: Int, kind: Lesson.Kind, title: String, sub: String,
                          words: [VocabCard], steps: [LessonStep]) -> Lesson {
    var numbered = steps
    for i in numbered.indices { numbered[i].id = i }
    return Lesson(key: "\(week.n).\(n)", weekN: week.n, n: n, kind: kind, title: title, sub: sub,
                  words: words.map(\.it), steps: numbered,
                  minutes: max(2, Int((Double(steps.count) / 3).rounded())))
}

/// All lessons for one week, in the order they should be taken.
public func weekLessons(_ week: Week, articles: [String]) -> [Lesson] {
    let all = week.vocab.filter { !$0.it.isEmpty && !$0.en.isEmpty }
    let chunks = balancedChunks(all)
    let grammar = grammarSteps(week)
    var lessons: [Lesson] = []

    for (i, words) in chunks.enumerated() {
        let n = lessons.count + 1
        let rng = SeededRandom("lesson:\(week.n):\(n)")
        let last = i == chunks.count - 1
        let steps = wordSteps(words, all: all, articles: articles, rng: rng) + (last ? grammar : [])
        let title = chunks.count > 1
            ? "Parole nuove \(i < romanNumerals.count ? romanNumerals[i] : String(i + 1))"
            : "Parole nuove"
        let sub = "\(words.count) new word\(words.count == 1 ? "" : "s")\(last && !grammar.isEmpty ? " + grammar" : "")"
        lessons.append(finishLesson(week, n: n, kind: .words, title: title, sub: sub, words: words, steps: steps))
    }

    let n = lessons.count + 1
    let rng = SeededRandom("lesson:\(week.n):\(n)")
    let passage = passageSteps(week, all: all, rng: rng)
    let body = (chunks.isEmpty ? grammar : []) + passage.steps
    if !body.isEmpty {
        lessons.append(finishLesson(week, n: n, kind: .passage, title: "Il brano",
                                    sub: week.r.isEmpty ? "The passage" : week.r,
                                    words: [], steps: body + passage.recap))
    }
    return lessons
}

// ── Checking ─────────────────────────────────────────────────────────────────

/// What a step's UI collects.
public enum LessonValue: Equatable {
    case text(String)
    case order([Int])   // build: chip indices in tap order
    case index(Int)     // choice / mc
    case bool(Bool)     // tf
    case done           // a cleared match board
}

public struct LessonVerdict: Equatable {
    /// nil when the step has no verdict.
    public let correct: Bool?
    public let answer: String
    public let note: String
}

public func isLessonStepReady(_ step: LessonStep, value: LessonValue?) -> Bool {
    switch step.kind {
    case .intro, .tip: return true
    case .match: return value == .done
    case .build:
        if case .order(let picked) = value { return picked.count == step.chips.count }
        return false
    case .choice, .mc:
        if case .index = value { return true }
        return false
    case .tf:
        if case .bool = value { return true }
        return false
    case .cloze, .recall, .drill, .transform:
        if case .text(let s) = value { return !s.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty }
        return false
    }
}

public func checkLessonStep(_ step: LessonStep, value: LessonValue?, articles: [String]) -> LessonVerdict {
    var typed = ""
    if case .text(let s) = value { typed = s }
    switch step.kind {
    case .cloze:
        let answer = step.answerText ?? ""
        return LessonVerdict(correct: checkAnswer(expected: answer, given: typed, articles: articles),
                             answer: answer, note: step.card?.exEn ?? "")
    case .recall:
        let answer = step.card?.it ?? ""
        return LessonVerdict(correct: checkAnswer(expected: answer, given: typed, articles: articles),
                             answer: answer, note: "")
    case .drill:
        let answer = step.answerText ?? ""
        return LessonVerdict(correct: checkDrill(expected: answer, given: typed), answer: answer, note: step.hint ?? "")
    case .transform:
        let answer = step.answerText ?? ""
        return LessonVerdict(correct: checkTransform(answer: answer, typed: typed), answer: answer, note: "")
    case .build:
        var picked: [String] = []
        if case .order(let order) = value {
            picked = order.compactMap { step.chips.indices.contains($0) ? step.chips[$0] : nil }
        }
        return LessonVerdict(correct: scrambleTokens(step.text ?? "") == picked,
                             answer: step.text ?? "", note: step.en ?? "")
    case .choice, .mc:
        let answer = step.answerIndex.flatMap { step.options.indices.contains($0) ? step.options[$0] : nil } ?? ""
        return LessonVerdict(correct: value == step.answerIndex.map(LessonValue.index),
                             answer: answer, note: step.kind == .mc ? (step.explain ?? "") : "")
    case .tf:
        return LessonVerdict(correct: value == step.answerBool.map(LessonValue.bool),
                             answer: step.answerBool == true ? "Vero" : "Falso", note: step.explain ?? "")
    case .intro, .tip, .match:
        return LessonVerdict(correct: nil, answer: "", note: "")
    }
}

/// The value that passes a graded step — what the tests replay a lesson with.
public func lessonSolution(_ step: LessonStep) -> LessonValue? {
    switch step.kind {
    case .cloze, .drill, .transform: return .text(step.answerText ?? "")
    case .recall: return .text(step.card?.it ?? "")
    case .choice, .mc: return step.answerIndex.map(LessonValue.index)
    case .tf: return step.answerBool.map(LessonValue.bool)
    case .build:
        var used = Set<Int>()
        return .order(scrambleTokens(step.text ?? "").map { tok in
            let i = step.chips.indices.first { step.chips[$0] == tok && !used.contains($0) } ?? -1
            used.insert(i)
            return i
        })
    case .intro, .tip, .match: return nil
    }
}

// ── Adapting a lesson to what the learner already knows ──────────────────────
// Twin of adaptLesson in lessonPlan.js. The plan stays deterministic; this runs
// when a lesson is started. A word seen KNOWN_REPS+ times at a KNOWN_DAYS+
// interval, not due and not relearning, loses its steps (the match board stays);
// a word missed WEAK_LAPSES+ times, or with low ease, gets one extra recall.

public let KNOWN_REPS = 3
public let KNOWN_DAYS = 14.0
public let WEAK_LAPSES = 2

public enum WordLevel: Equatable { case normal, known, weak }

public func wordLevel(_ st: SRSCard?, now: Double) -> WordLevel {
    guard let st else { return .normal }
    if st.lapses >= WEAK_LAPSES || st.ease < WEAK_EASE { return .weak }
    if st.reps >= KNOWN_REPS && st.interval >= KNOWN_DAYS && st.due > now && st.relearn == nil { return .known }
    return .normal
}

public func adaptLesson(_ lesson: Lesson, store: SRSStore, now: Double) -> Lesson {
    guard lesson.kind == .words else { return lesson }
    var known = Set<String>()
    var weak: [String] = []
    for term in lesson.words {
        switch wordLevel(store[term], now: now) {
        case .known: known.insert(term)
        case .weak: weak.append(term)
        case .normal: break
        }
    }
    if (known.isEmpty && weak.isEmpty) || known.count == lesson.words.count { return lesson }

    let adaptedKinds: Set<LessonStep.Kind> = [.intro, .choice, .cloze, .build, .recall]
    var steps = lesson.steps.filter { step in
        !(step.term.map(known.contains) ?? false && adaptedKinds.contains(step.kind))
    }
    let extras: [LessonStep] = weak.compactMap { term in
        guard let card = lesson.steps.first(where: { $0.term == term && $0.card != nil })?.card else { return nil }
        var step = LessonStep(.recall)
        step.term = term
        step.card = card
        step.practice = true
        return step
    }
    let lastRecall = steps.lastIndex { $0.kind == .recall && !$0.practice }
    steps.insert(contentsOf: extras, at: lastRecall.map { $0 + 1 } ?? steps.count)
    for i in steps.indices { steps[i].id = i }

    return Lesson(key: lesson.key, weekN: lesson.weekN, n: lesson.n, kind: lesson.kind,
                  title: lesson.title, sub: lesson.sub, words: lesson.words, steps: steps,
                  minutes: max(2, Int((Double(steps.count) / 3).rounded())),
                  adapted: LessonAdaptation(skipped: known.count, extra: extras.count))
}

// ── A run through a lesson ───────────────────────────────────────────────────
// A missed graded step comes back once at the end of the queue. Only the first
// attempt counts toward the score and the SRS; the retry is practice.

public struct LessonRun: Equatable {
    public var queue: [LessonStep]
    public var index = 0
    /// Step id → whether its first attempt was right.
    public var first: [Int: Bool] = [:]

    public init(_ lesson: Lesson) { queue = lesson.steps }

    public var current: LessonStep? { queue.indices.contains(index) ? queue[index] : nil }
    public var isFinished: Bool { index >= queue.count }
    public var progress: Double { queue.isEmpty ? 1 : min(1, Double(index) / Double(queue.count)) }

    /// `correct` is the verdict from checkLessonStep (nil for ungraded steps).
    public func advanced(correct: Bool?) -> LessonRun {
        guard let step = current else { return self }
        var next = self
        if let correct, step.isGraded {
            if !step.retry, next.first[step.id] == nil { next.first[step.id] = correct }
            if !correct, !step.retry {
                var again = step
                again.retry = true
                next.queue.append(again)
            }
        }
        next.index += 1
        return next
    }

    public var summary: LessonSummary {
        let correct = first.values.filter { $0 }.count
        let graded = first.count
        return LessonSummary(graded: graded, correct: correct,
                             pct: graded > 0 ? Int((Double(correct) / Double(graded) * 100).rounded()) : 100)
    }
}

public struct LessonSummary: Equatable {
    public let graded: Int
    public let correct: Int
    public let pct: Int
}

public struct LessonGrade: Equatable {
    public let term: String
    public let grade: SRSGrade
}

/// SRS grades earned by a run, one per word typed from memory: a missed recall
/// is `again`, a good recall after a missed fill-the-blank is `hard`, otherwise
/// `good`. Taps never count, and a word already scheduled and not yet due is
/// left alone so repeating a lesson cannot inflate its interval.
public func lessonSrsGrades(_ lesson: Lesson, run: LessonRun, store: SRSStore, now: Double) -> [LessonGrade] {
    var order: [String] = []
    var recall: [String: Bool] = [:]
    var other: [String: Bool] = [:]
    for step in lesson.steps where step.isTyped {
        guard let term = step.term, let result = run.first[step.id] else { continue }
        if recall[term] == nil && other[term] == nil { order.append(term) }
        if step.kind == .recall { recall[term] = result }
        else { other[term] = (other[term] ?? true) && result }
    }
    return order.compactMap { term in
        guard let recalled = recall[term] else { return nil }
        if let st = store[term], st.due > now { return nil }
        return LessonGrade(term: term, grade: !recalled ? .again : (other[term] ?? true) ? .good : .hard)
    }
}

// ── lessonStore.js ───────────────────────────────────────────────────────────
// Persisted under `<prefix>-lessons` in the web's exact JSON, so finished
// lessons ride along in a backup file both ways.

public struct LessonRecord: Codable, Equatable {
    public var date: String
    public var pct: Int
    public var times: Int

    public init(date: String, pct: Int, times: Int = 1) {
        self.date = date
        self.pct = pct
        self.times = times
    }

    public init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        date = (try? c.decode(String.self, forKey: .date)) ?? ""
        pct = Int(((try? c.decode(Double.self, forKey: .pct)) ?? 0).rounded())
        times = (try? c.decode(Int.self, forKey: .times)) ?? 1
    }
}

public struct LessonStore: Codable, Equatable {
    public var done: [String: LessonRecord] = [:]

    public init() {}

    public init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        done = (try? c.decode([String: LessonRecord].self, forKey: .done)) ?? [:]
    }

    public func isDone(_ key: String) -> Bool { done[key] != nil }

    /// Redoing a lesson keeps the best score and the first date, and counts.
    public func completing(_ key: String, pct: Int, date: String) -> LessonStore {
        var next = self
        if let prev = done[key] {
            next.done[key] = LessonRecord(date: prev.date, pct: max(prev.pct, pct), times: prev.times + 1)
        } else {
            next.done[key] = LessonRecord(date: date, pct: pct)
        }
        return next
    }

    public func progress(_ lessons: [Lesson]) -> (done: Int, total: Int) {
        (lessons.filter { isDone($0.key) }.count, lessons.count)
    }

    /// True when the week has lessons and every one is finished.
    public func isWeekComplete(_ lessons: [Lesson]) -> Bool {
        !lessons.isEmpty && lessons.allSatisfy { isDone($0.key) }
    }
}

public struct WeekPlan: Equatable {
    public let weekN: Int
    public let lessons: [Lesson]

    public init(weekN: Int, lessons: [Lesson]) {
        self.weekN = weekN
        self.lessons = lessons
    }
}

public enum LessonAction: Equatable {
    case lesson(Lesson, ahead: Bool)
    case review(due: Int)
    case done
}

/// What the "Continue" button should do: the current week's next lesson, else
/// the review when cards are due, else a later week's lesson early, else
/// nothing. With no current week the course is taken from the top.
public func nextLessonAction(plans: [WeekPlan], store: LessonStore, currentWeekN: Int?, due: Int) -> LessonAction {
    func firstOpen(_ list: [WeekPlan]) -> Lesson? {
        for p in list {
            if let lesson = p.lessons.first(where: { !store.isDone($0.key) }) { return lesson }
        }
        return nil
    }
    guard let currentWeekN else {
        if let lesson = firstOpen(plans) { return .lesson(lesson, ahead: false) }
        return due > 0 ? .review(due: due) : .done
    }
    if let lesson = firstOpen(plans.filter { $0.weekN == currentWeekN }) { return .lesson(lesson, ahead: false) }
    if due > 0 { return .review(due: due) }
    if let lesson = firstOpen(plans.filter { $0.weekN > currentWeekN }) { return .lesson(lesson, ahead: true) }
    return .done
}

// ── reviewMix.js ─────────────────────────────────────────────────────────────

public enum ReviewStyle: String, Equatable {
    case recognition, cloze, recall
}

public let CLOZE_FROM_REPS = 2
public let RECALL_FROM_REPS = 4

/// "Smart mix": recognition while a card is new or relearning, cloze after a
/// couple of successes (when its example allows), full recall once established.
public func reviewStyle(for card: VocabCard, state: SRSCard?, articles: [String]) -> ReviewStyle {
    guard let st = state, st.reps >= CLOZE_FROM_REPS, st.relearn == nil else { return .recognition }
    if st.reps < RECALL_FROM_REPS, isClozeEligible(card: card, articles: articles) { return .cloze }
    return .recall
}
